  // work/native-parser-migration/智慧订单原始引擎/desktop/wechat-heading.js
  function stripWechatHeadings(text) {
    if (typeof text !== "string") return text;
    return text.split(/\r?\n/).map((line) => {
      const m = line.trim().match(/^([^:：]{1,100})[:：]$/);
      if (!m) return line;
      const name = m[1].trim();
      if (!/[^0-9０-９\s.,，、/\-]/.test(name)) return line;
      if (/^(总额|總額|合计|合計|金额|金額|备注|備註|澳门|澳門|香港|港澳|老澳门|特码|特碼|平码|平碼|平特|平特一肖|特肖|三连|四连|三连肖|四连肖)$/.test(name)) return line;
      if (/^[鼠牛虎兔龙龍蛇马馬羊猴鸡雞狗猪豬单双單雙大小红紅蓝藍绿綠0-9０-９\s,，、./-]+$/.test(name)) return line;
      return "";
    }).join("\n");
  }

